WITH RECURSIVE CTE AS ( SELECT d.target_path FROM dependency d WHERE d.source_path IN
#{path}
AND d.site = #{siteId} AND d.valid = 1 UNION SELECT d.target_path FROM cte, dependency d WHERE cte.target_path = d.source_path AND d.site = #{siteId} AND d.valid = 1 ) SELECT cte.target_path as path, i.label AS meta_label, i.system_type AS meta_system_type, i.mime_type AS meta_mime_type FROM cte INNER JOIN item i ON i.path = cte.target_path INNER JOIN site s ON s.id = i.site_id AND s.site_id = #{siteId} AND s.deleted = 0 AND (i.state & #{modifiedMask}) > 0 AND (i.state & #{newMask}) = 0 AND
cte.target_path NOT RLIKE #{pattern}

SELECT DISTINCT d.target_path AS path, i.label AS meta_label, i.mime_type AS meta_mime_type, i.system_type AS meta_system_type FROM dependency d INNER JOIN site s ON s.site_id = d.site INNER JOIN item i ON i.path = d.target_path INNER JOIN item_target it ON it.item_id = i.id AND it.target = #{target} WHERE d.source_path IN
#{path}
AND d.target_path NOT IN
#{path}
AND d.site = #{siteId} AND d.valid = 1 AND
d.target_path NOT RLIKE #{pattern}
AND i.site_id = s.id AND s.deleted = 0 AND (i.state & #{modifiedMask}) > 0 AND (i.state & #{newMask}) = 0 AND (it.previous_path IS NULL)

mapper.sql:
SELECT i.id, i.path, i.parent_id, i.system_type, i.state, i.label, i.mime_type FROM item i INNER JOIN site s on s.id = i.site_id WHERE i.path IN
#{path}
AND s.site_id = #{siteId} AND s.deleted = 0 UNION SELECT id, path, parent_id, system_type, state, label, mime_type FROM ( SELECT i.id, i.path, i.parent_id, i.system_type, i.state, i.label, i.mime_type FROM item i INNER JOIN parents p ON p.parent_id = i.id WHERE ((i.state & #{newInTargetMaskOn}) = #{newInTargetMaskOn} AND (i.state & #{newInTargetMaskOff}) = 0) OR EXISTS ( SELECT 1 FROM item_target it WHERE it.item_id = i.id AND it.previous_path IS NOT NULL
AND it.target = #{target}
) UNION
) AS parents_deps

SELECT targetItem.id, targetItem.path, targetItem.parent_id, targetItem.system_type, targetItem.state, targetItem.label, targetItem.mime_type
FROM item targetItem
INNER JOIN dependency d ON d.target_path = targetItem.path
INNER JOIN ${tableName} p ON d.source_path = p.path
INNER JOIN site s ON s.id = targetItem.site_id
WHERE d.site = #{siteId}
AND s.site_id = #{siteId}
AND s.deleted = 0
AND d.valid = 1
AND (
	((targetItem.state & #{newInTargetMaskOn}) = #{newInTargetMaskOn} 
	AND (targetItem.state & #{newInTargetMaskOff}) = 0)
	OR
	(


			targetItem.path RLIKE #{pattern}

	)

	OR EXISTS (SELECT 1 FROM item_target it WHERE it.item_id = targetItem.id AND it.target = #{target} AND it.previous_path IS NOT NULL)
)

SELECT id, path, parent_id, system_type, state, label, mime_type FROM parents p WHERE p.system_type <> #{systemTypeFolder} UNION SELECT id, path, parent_id, system_type, state, label, mime_type FROM ( SELECT i.id, i.path, i.parent_id, i.system_type, i.state, i.label, i.mime_type FROM item i INNER JOIN children c ON c.id = i.parent_id WHERE (i.state & #{newInTargetMaskOn}) <> #{newInTargetMaskOn} AND (i.state & #{newInTargetMaskOff}) > 0 AND EXISTS ( SELECT 1 FROM item_target it WHERE it.item_id = c.id AND it.previous_path IS NOT NULL
AND it.target = #{target}
) UNION
) AS children_deps

